//! Syntax highlighting for source views.
//!
//! Highlighting is a best-effort decoration: a file whose language we cannot
//! recognise, or one giallo fails on, stays exactly as the plain text view
//! rendered it. The views lay out one row per line themselves, so we use
//! [`HtmlRenderer::render_lines`] rather than the `<pre>` renderer.

use giallo::{HighlightOptions, HtmlRenderer, Registry, RenderOptions, ThemeVariant};
use std::cell::OnceCell;
use std::rc::Rc;

const THEME: &str = "github-light-high-contrast";
/// generated by `build.rs`.
const BUILTIN: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/builtin.zst"));

thread_local! {
    static REGISTRY: OnceCell<Option<Rc<Registry>>> = const { OnceCell::new() };
}

/// Highlight `lines` as `filename`'s language, returning one HTML fragment per
/// line.
///
/// `None` means "render the plain lines": the filename has no language we know,
/// giallo could not load, or highlighting failed. The returned vector always
/// has the same length as `lines` when it is `Some`.
pub(crate) fn highlight_lines(filename: &str, lines: &[String]) -> Option<Vec<String>> {
    if lines.is_empty() {
        return None;
    }
    let language = language_for_filename(filename)?;
    let registry = registry()?;
    if !registry.contains_grammar(&language) {
        return None;
    }

    let content = lines.join("\n");
    let options = HighlightOptions::new(&language, ThemeVariant::Single(THEME));
    let highlighted = registry.highlight(&content, &options).ok()?;
    let mut rendered = renderer().render_lines(&highlighted, &RenderOptions::default());
    // `render_lines` preserves giallo's token lines, including the trailing
    // empty one a final newline produces. The view's `split_lines` deliberately
    // drops that line, so trim back to the table's row count.
    rendered.truncate(lines.len());
    (rendered.len() == lines.len()).then_some(rendered)
}

fn renderer() -> HtmlRenderer {
    HtmlRenderer {
        css_class_prefix: Some("g-".to_string()),
        ..Default::default()
    }
}

fn registry() -> Option<Rc<Registry>> {
    REGISTRY.with(|cell| {
        cell.get_or_init(|| {
            let mut registry = Registry::load(BUILTIN).ok()?;
            registry.link_grammars();
            Some(Rc::new(registry))
        })
        .clone()
    })
}

/// The giallo grammar name/alias for a filename.
///
/// Giallo's aliases include most file extensions (`rs`, `js`, `py`, `md`, ...),
/// so the extension is the language by default. A few files carry their
/// language entirely in their name.
fn language_for_filename(filename: &str) -> Option<String> {
    let filename = filename.rsplit('/').next().unwrap_or(filename);
    let lower = filename.to_ascii_lowercase();
    let named = match lower.as_str() {
        "makefile" | "gnumakefile" => Some("make"),
        "dockerfile" | "containerfile" => Some("docker"),
        "cmakelists.txt" => Some("cmake"),
        _ => None,
    };
    if let Some(named) = named {
        return Some(named.to_string());
    }

    let (_, extension) = lower.rsplit_once('.')?;
    // The plain grammar advertises these aliases too, but there is nothing to
    // highlight: leave plain text to the normal escaped path.
    if matches!(extension, "txt" | "text") {
        return None;
    }
    (!extension.is_empty()).then(|| extension.to_string())
}

#[cfg(test)]
mod tests {
    use super::*;

    fn lines(text: &str) -> Vec<String> {
        let mut lines: Vec<String> = text.split('\n').map(String::from).collect();
        if lines.last().is_some_and(String::is_empty) {
            lines.pop();
        }
        lines
    }

    #[test]
    fn test_highlights_a_known_language() {
        let html = highlight_lines("src/main.rs", &lines("fn main() {}\n")).unwrap();
        assert_eq!(html.len(), 1);
        assert!(html[0].contains(r#"class="giallo-l""#), "{html:?}");
        assert!(html[0].contains(r#"<span class="g-"#), "{html:?}");
    }

    #[test]
    fn test_unknown_extension_stays_plain() {
        assert_eq!(
            highlight_lines("notes.unknown-extension", &lines("hello\n")),
            None
        );
    }

    #[test]
    fn test_highlighted_line_count_matches_the_table() {
        let html =
            highlight_lines("src/main.rs", &lines("fn main() {\n    let x = 1;\n}\n")).unwrap();
        assert_eq!(html.len(), 3);
    }

    #[test]
    fn test_filename_can_name_the_language() {
        assert_eq!(
            language_for_filename("docs/Makefile").as_deref(),
            Some("make")
        );
        assert_eq!(language_for_filename("src/main.rs").as_deref(), Some("rs"));
        assert_eq!(language_for_filename("README"), None);
    }
}
